package com.hollowfrontier.registry;

import com.hollowfrontier.HollowFrontier;

import net.minecraft.core.Holder;
import net.minecraft.core.registries.Registries;
import net.minecraft.data.worldgen.BootstrapContext;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.damagesource.DamageType;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.level.Level;

// Damage types are a datapack registry: keys here, entries generated by datagen (bootstrap below).
public final class ModDamageTypes {
    private ModDamageTypes() {}

    public static final ResourceKey<DamageType> BULLET = ResourceKey.create(Registries.DAMAGE_TYPE, HollowFrontier.id("bullet"));
    /** 12b: a beam of phlogiston light: the guardians', the sentinels', the Archon's and the Sunstone Lens's. The Starsteel Crown halves it. */
    public static final ResourceKey<DamageType> PHLOGISTON_BEAM = ResourceKey.create(Registries.DAMAGE_TYPE, HollowFrontier.id("phlogiston_beam"));

    public static void bootstrap(BootstrapContext<DamageType> context) {
        context.register(BULLET, new DamageType(HollowFrontier.MODID + ".bullet", 0.1F));
        context.register(PHLOGISTON_BEAM, new DamageType(HollowFrontier.MODID + ".phlogiston_beam", 0.1F));
    }

    /** A phlogiston beam fired by {@code attacker} (straight from it, with no projectile between). */
    public static DamageSource phlogistonBeam(Entity attacker) {
        return new DamageSource(holder(attacker.level(), PHLOGISTON_BEAM), attacker, attacker);
    }

    public static Holder<DamageType> holder(Level level, ResourceKey<DamageType> key) {
        return level.registryAccess().lookupOrThrow(Registries.DAMAGE_TYPE).getOrThrow(key);
    }
}
